-- S295 (SkyHarbor), 2026-09-27: Rule 8 ingest - five rows, INSERT-only, idempotent on slug.
-- Two milestones and a procedure from this session's work (ESL apply, prompt audit, ESL monthly pass) and two pitfalls
-- (the context meter in three-repo sessions; a workflow that rewrites an input must rebuild what reads it).
-- Own rows land verified only where a committed source corroborates them (receipts, a merged PR, a committed script);
-- the two tied to unmerged PRs land proposed. Summary is one sentence of at most 400 characters.
-- Rollback: delete from cpl_memory_log where actor = 'SkyHarbor-s295';
--           delete from cpl_memory where author = 'SkyHarbor-s295';
insert into public.cpl_memory (slug, kind, org, title, summary, detail, plain, tags, source, related, status, verified_by, verified_at, event_date, author)
select x.slug, x.kind, 'cpl', x.title, x.summary, x.detail, x.plain, x.tags, x.source, '{}'::text[], x.status, x.verified_by,
       case when x.status = 'verified' then now() end, date '2026-09-27', 'SkyHarbor-s295'
from jsonb_to_recordset($json$[{"slug": "esl-sheet-apply-landed-2026-09-27", "kind": "milestone", "title": "The ESL sheets are applied: 147 + 2 rows, six cohorts read back", "summary": "The ESL merging sheet and its follow-up were applied on 2026-09-27 through esl-sheet-apply.yml, 147 plus 2 rows with none held, and the live table reads back all six cohorts: catalog 6, health 18, ladder 30, newfold 89, transfer 3 and vesl 2.", "detail": "Dispatched by S295 (dry-run, then commit, one run at a time because the workflow shares the daily cron's concurrency group and a second queued run would cancel a pending cron run). Receipts: kb/esl_sheet_out/2026-09-26/applied_2026-09-27T115648Z.json and kb/esl_sheet_out/2026-09-27/applied_2026-09-27T120326Z.json, each with every row's before-values; one rollback dispatch per plan dir restores them. FTVE M1018 carries no merge row. The daily run 2cc2f03 published the changes the same day. Sam's two Complete threads were answered and resolved.", "plain": "The ESL grouping changes Sam approved are now live. Every planned change went in, the database counts match the plan, and the saved receipts can undo them in one step.", "tags": ["esl-packaging", "kb_curation", "rule-10", "decision-sheet"], "source": "S295 receipts in kb/esl_sheet_out/ and a live read 2026-09-27", "status": "verified", "verified_by": "the commit receipts and a live cohort count (S295)"}, {"slug": "context-meter-silent-in-three-repo-sessions", "kind": "pitfall", "title": "The context meter never fires in a three-repo session", "summary": "A three-repo session loads none of the tracker's .claude/settings.json, so the PostToolUse context meter Rule 9a describes never fires there, and a session has to run python3 kb/_context_budget.py itself at session start, after a long stretch and before sign-off.", "detail": "scripts/check_hooks_live.py records it (measured 2026-09-19): with three repos attached the session root is their parent, and nothing in the repo's settings loads, the PostToolUse context-budget probe included. Its --fix installs only the PreToolUse guards at the root (scripts/install_prompt_guards.py); scripts/install-context-hook.ps1 registers the meter at user level on Sam's Windows machine only. The CLAUDE.md fix is card 1 of the CLAUDE.md Cleanup sheet (https://claude.ai/artifact/Kd6K7yrAfGQKCtVyd4bhX5), with the option to install the meter at the root.", "plain": "The automatic warning before a session runs out of memory does not work in the usual cloud setup, so a session has to check its own memory use.", "tags": ["context-pressure", "rule-9", "hooks", "three-repo"], "source": "scripts/check_hooks_live.py docstring; CLAUDE.md prompt audit 2026-09-27 (finding F1)", "status": "verified", "verified_by": "scripts/check_hooks_live.py (measured 2026-09-19)"}, {"slug": "a-workflow-that-rewrites-an-input-rebuilds-its-readers", "kind": "pitfall", "title": "A workflow that rewrites an input must rebuild what reads it", "summary": "When a workflow rewrites a file that a committed artifact is built from, the same run has to rebuild that artifact, because the daily run that carried the ESL writes into kb/coci_curation.json left prototype/ccr_remint_blast.json stale and turned main and every open PR red on its --check.", "detail": "Found 2026-09-27 (S295): the first curation change to reach coci_curation.json through the daily run, rather than a session PR that rebuilt its artifacts, exposed two data-coupled checks. Fixed in #1709: daily-dashboard.yml Step 4d7 rebuilds the blast radius, and tests/legacy_anchor_duplicates_test.py's lane count subtracts anchors that already carry merge_into (8 ESL anchors folded that day), matching its own section-6 unit check. The lints job stops at its first failing step, so run every step locally (scripts in the S295 notes) before calling a base red fixed.", "plain": "When the nightly job updates a data file, it also has to rebuild everything made from that file, or the automated checks fail for everyone.", "tags": ["daily-dashboard", "ci", "generated-artifacts", "esl-packaging"], "source": "PR #1709", "status": "verified", "verified_by": "merged PR #1709"}, {"slug": "claude-md-prompt-audit-2026-09-27", "kind": "milestone", "title": "CLAUDE.md prompt audit: narratives moved, eight calls to Sam", "summary": "The 2026-09-27 prompt audit moved CLAUDE.md's incident narratives verbatim to docs/reference/doctrine_provenance.md with every rule left in place, brought the file under its 60,000-byte budget, and sent eight decisions to Sam as the CLAUDE.md Cleanup sheet.", "detail": "Queue item 0 of handoff 295 (Sam, 2026-09-27: \"Thinking we should clean up claude.md\"), run as /claude-api prompt-audit over the three always-loaded CLAUDE.md files. Report kb/prompt_audit/20260927_claude_md_prompt_audit.md (17 findings). Applied: 15 hunks (history narratives, migration-relative phrasing), 61,867 -> 59,436 bytes; the loss audit found every Critical Rule and the section order unchanged. Proposed on the sheet (https://claude.ai/artifact/Kd6K7yrAfGQKCtVyd4bhX5, kb/_build_claude_md_audit_decision_sheet.py): Rule 9a's meter, the open-asks republish conflict, four tracker stale facts, the vault's 2025 plans and skill count, the knowledge base's title/rule number/local clone, the warning-mark level, and two vault-updater questions. PR #1708.", "plain": "The main instruction file for Claude sessions was tidied without changing any rule, and the choices only Sam can make went to him on one sheet.", "tags": ["doctrine", "claude-md", "prompt-audit", "decision-sheet"], "source": "PR #1708; kb/prompt_audit/20260927_claude_md_prompt_audit.md", "status": "proposed", "verified_by": null}, {"slug": "esl-monthly-pass-procedure", "kind": "procedure", "title": "The ESL monthly pass", "summary": "The ESL monthly pass Sam approved on 2026-09-26 runs from kb/_esl_monthly_pass.py, applies what a level or purpose word places through esl-sheet-apply.yml under esl-monthly-s<N>@bot, lists the rest for him, never re-lists the six identities he ruled apart, and the docs lint flags it 31 days after the last pass.", "detail": "Item 8 of the ESL merging sheet, as proposed. Steps: python3 kb/_esl_monthly_pass.py --session N writes kb/esl_sheet_out/<date>-monthly/plan.json; if it applies anything, dispatch esl-sheet-apply.yml with that plan_dir (dry-run, then commit); hand Sam what it lists on a sheet. Kept apart: M1205, M1239, M10KY, M10PO, M10PN (item 4) and M9309 (follow-up). First pass 2026-09-27: nothing to apply or list. Cadence CA-08; lint esl_monthly_pass_due. PR #1710.", "plain": "Once a month a session places any new ESL courses into the right group, applies the clear cases, and sends Sam the unclear ones.", "tags": ["esl-packaging", "cadence", "governance", "kb_curation"], "source": "PR #1710", "status": "proposed", "verified_by": null}]$json$::jsonb)
  as x(slug text, kind text, title text, summary text, detail text, plain text, tags text[], source text, status text, verified_by text)
where not exists (select 1 from public.cpl_memory m where m.slug = x.slug);
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select id, 'SkyHarbor-s295', 'create', 'S295 checkpoint', to_jsonb(m) from public.cpl_memory m
where m.slug in ('esl-sheet-apply-landed-2026-09-27', 'context-meter-silent-in-three-repo-sessions', 'a-workflow-that-rewrites-an-input-rebuilds-its-readers', 'claude-md-prompt-audit-2026-09-27', 'esl-monthly-pass-procedure')
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');
select m.slug, m.status, (select count(*) from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create') as creates
from public.cpl_memory m where m.slug in ('esl-sheet-apply-landed-2026-09-27', 'context-meter-silent-in-three-repo-sessions', 'a-workflow-that-rewrites-an-input-rebuilds-its-readers', 'claude-md-prompt-audit-2026-09-27', 'esl-monthly-pass-procedure') order by 1;
